-- Slice 1 / T1.17 follow-up (security review). CHECK generated by drizzle-kit; triggers below are hand-written.
ALTER TABLE "fields" ADD CONSTRAINT "fields_column_name_identifier" CHECK ("fields"."column_name" ~ '^[a-z_][a-z0-9_]{0,62}$');--> statement-breakpoint

-- Which real column a system field maps to is fixed at creation.
CREATE FUNCTION fields_system_immutable() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.is_system IS DISTINCT FROM OLD.is_system OR NEW.column_name IS DISTINCT FROM OLD.column_name THEN
    RAISE EXCEPTION 'fields: is_system and column_name are immutable' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;--> statement-breakpoint
CREATE TRIGGER fields_system_immutable BEFORE UPDATE OF is_system, column_name ON fields FOR EACH ROW EXECUTE FUNCTION fields_system_immutable();--> statement-breakpoint

-- AUDIT columns come from the transaction's context, never from the caller, so they cannot be spoofed.
CREATE FUNCTION app.set_audit_columns() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE actor uuid := NULLIF(current_setting('app.user_id', true), '')::uuid;
BEGIN
  IF actor IS NULL THEN RAISE EXCEPTION '%: app.user_id is not set', TG_TABLE_NAME USING ERRCODE = 'insufficient_privilege'; END IF;
  IF TG_OP = 'INSERT' THEN
    NEW.created_by := actor; NEW.created_at := now();
  ELSE
    NEW.created_by := OLD.created_by; NEW.created_at := OLD.created_at;
  END IF;
  NEW.updated_by := actor; NEW.updated_at := now();
  RETURN NEW;
END $$;--> statement-breakpoint
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['modules', 'fields', 'picklists', 'picklist_values', 'layouts', 'layout_sections', 'layout_fields', 'field_permissions'] LOOP
    EXECUTE format('CREATE TRIGGER %I BEFORE INSERT OR UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION app.set_audit_columns()', t || '_audit', t);
  END LOOP;
END $$;
